import classes from './StepsSection.module.css';

const StepsSection = ({ t }) => {
  return (
    <div className="section line-dark">
      <div className="container">
        <div className="content">
          <h2 className='h2'>Как забронировать</h2>

          <ul className={classes.list}>
            {t.items.map(step => (
              <li key={step.id} className={classes.item}>
                {/* <p className={`${classes.step} text-base`}></p> */}
                <p className={`${classes.label} h3`}>{step.num} {step.label}</p>
                <p className={`${classes.body} text-sm`}>{step.text}</p>
              </li>
            ))}
          </ul>
          
        </div>
      </div>
    </div>
  );
};

export default StepsSection;
